#!/usr/bin/env python3
"""
Round 133b (culprits), 2 October 2026. Needs round 132b.

Combine the ticked layers cuts the layers to where they meet.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 133b (2 October)\n\nNeeds round 132b. No tiles patch. No app.js?v= bump.\n\n- Combine the ticked layers now cuts the ticked layers to where they meet,\n  instead of drawing one surface in their place (asked 2 October). "Where\n  they overlap the most": only the squares (0.25 degrees, each layer present\n  within about 200 km) where the most ticked layers meet, two at least.\n  "Where their highest values overlap": only the squares where the most\n  layers are each in the top fifth of their own values (COMBO_TOP).\n- The cut is a MapLibre "within" filter added to each layer\'s own filter\n  (COMBO_OWN; a setFilter wrapper keeps later filter changes, comboExpr turns\n  old-style filters into expressions). Layers are never hidden, so tiled\n  layers keep loading; what the map has seen of them is kept (COMBO.seen) and\n  the cut is made again as the map moves. Areas (fill layers) count but show\n  whole ("within" cannot cut them); pictures take no part; the box names both.\n- The weights menu is now "takes part" / "left out". No 3D, no raised ground.\n- Checked in Chromium (MapLibre 5.24): a within filter joined to a layer\'s own\n  filter shows only the points inside. The whole map was not run in a browser.\n\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round133b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 132b" not in h.read_text(encoding="utf-8"):
        sys.exit("round133b: round 132b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round133b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round133b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round133b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
